"use client";

import { usePathname } from "next/navigation";
import Link from "next/link";
import { ReactNode, use, useState, useEffect } from "react";
import { usePostPaymentApplication } from "@/app/lib/hooks/usePostPaymentApplication";
import { LoadingSpinner } from "@/app/components/ui/Loader";
import Header from "@/app/components/layout/Header";

interface Step {
  number: number;
  label: string;
  path: string;
}

const STEPS: Step[] = [
  { number: 1, label: "Personal Info", path: "/step-1-personal" },
  { number: 2, label: "Passport", path: "/step-2-passport" },
  { number: 3, label: "U.S. Travel", path: "/step-3-us-travel" },
  { number: 4, label: "Contact", path: "/step-4-contact" },
  { number: 5, label: "Employment", path: "/step-5-employment" },
  { number: 6, label: "Eligibility", path: "/step-6-eligibility" },
  { number: 7, label: "Review", path: "/step-7-review" },
];

export default function ApplicationLayout({
  children,
  params: paramsPromise,
}: {
  children: ReactNode;
  params: Promise<{ id: string }>;
}) {
  const pathname = usePathname();
  const params = use(paramsPromise);
  const { loadApplication, isLoading, error, application } = usePostPaymentApplication();

  const currentStepIndex = STEPS.findIndex((step) => pathname.includes(step.path));
  const currentStep = currentStepIndex >= 0 ? currentStepIndex + 1 : 1;

  // Load application data once on mount
  useEffect(() => {
    if (params.id) {
      loadApplication(params.id);
    }
  }, [params.id, loadApplication]);

  // Show loading state while fetching application
  if (isLoading) {
    return (
      <div className="min-h-screen bg-white flex items-center justify-center">
        <LoadingSpinner />
      </div>
    );
  }

  // Show error state if failed to load
  if (error) {
    return (
      <div className="min-h-screen bg-white">
        <Header />
        <div className="max-w-3xl mx-auto px-4 py-12 text-center">
          <div className="bg-red-50 border border-red-200 text-red-800 px-6 py-6 rounded-lg">
            <p className="font-semibold text-lg mb-2">Unable to load application</p>
            <p className="text-sm mb-4">{error}</p>
            <Link
              href="/"
              className="inline-block px-6 py-2 bg-primary text-white rounded-md hover:bg-primary-light transition-colors font-medium"
            >
              Return to Home
            </Link>
          </div>
        </div>
      </div>
    );
  }

  const totalTravelers = application?.travelers?.length || 1;

  return (
    <div className="min-h-screen bg-white">
      {/* Header */}
      <Header />

      {/* Progress Bar */}
      <div className="w-full bg-white max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6 pt-8 lg:py-12 border-b border-gray-200">
        <div className="flex items-center justify-between">
          {STEPS.map((step, index) => {
            const isCompleted = step.number < currentStep;
            const isCurrent = step.number === currentStep;

            return (
              <div key={step.number} className="flex items-center flex-1">
                {/* Step Circle */}
                <div className="flex flex-col items-center sm:items-start">
                  <div
                    className={`w-8 h-8 rounded-full flex items-center justify-center text-sm font-semibold transition-all
                               ${
                                 isCompleted
                                   ? "bg-primary text-white"
                                   : isCurrent
                                   ? "bg-primary text-white"
                                   : "bg-gray-lightest text-gray border-2 border-gray-light"
                               }`}
                  >
                    {isCompleted ? (
                      <svg
                        className="w-5 h-5"
                        fill="currentColor"
                        viewBox="0 0 20 20"
                      >
                        <path
                          fillRule="evenodd"
                          d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z"
                          clipRule="evenodd"
                        />
                      </svg>
                    ) : (
                      step.number
                    )}
                  </div>

                  {/* Step Label */}
                  <span
                    className={`mt-2 text-xs sm:text-sm font-medium hidden sm:block
                               ${isCurrent ? "text-gray-dark" : "text-gray"}`}
                  >
                    {step.label}
                  </span>
                </div>

                {/* Connector Line */}
                {index < STEPS.length - 1 && (
                  <div className="flex-1 h-0.5 mx-2 sm:mx-4">
                    <div
                      className={`h-full transition-all
                                 ${
                                   step.number < currentStep
                                     ? "bg-primary"
                                     : "bg-gray-light"
                                 }`}
                    />
                  </div>
                )}
              </div>
            );
          })}
        </div>
      </div>

      {/* Main Content with Sidebar */}
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="grid md:grid-cols-12 gap-8 py-8">
          {/* Left Column - Form Content */}
          <div className="md:col-span-7">
            {children}
          </div>

          {/* Right Column - Application Summary Sidebar (Desktop Only) */}
          <div className="hidden md:block md:col-span-5">
            <div className="bg-white rounded-lg border border-gray-light p-6 shadow-sm sticky top-24">
              {/* Application Info */}
              <div className="mb-6">
                <h3 className="text-lg font-bold text-gray-dark mb-4">
                  Application Progress
                </h3>

                <div className="space-y-3 text-sm">
                  <div className="flex items-center justify-between">
                    <span className="text-gray">Application ID</span>
                    <span className="font-mono text-gray-dark font-semibold">
                      {params?.id?.slice(0, 8)}
                    </span>
                  </div>

                  <div className="flex items-center justify-between">
                    <span className="text-gray">Travelers</span>
                    <span className="font-semibold text-gray-dark">
                      {totalTravelers}
                    </span>
                  </div>

                  <div className="flex items-center justify-between">
                    <span className="text-gray">Step</span>
                    <span className="font-semibold text-gray-dark">
                      {currentStep} of {STEPS.length}
                    </span>
                  </div>
                </div>
              </div>

              {/* Steps List */}
              <div className="border-t border-gray-light pt-5">
                <div className="space-y-2">
                  {STEPS.map((step) => {
                    const isCompleted = step.number < currentStep;
                    const isCurrent = step.number === currentStep;

                    return (
                      <div
                        key={step.number}
                        className={`flex items-center gap-3 px-3 py-2 rounded-md ${
                          isCurrent
                            ? "bg-gray-lightest"
                            : ""
                        }`}
                      >
                        <div
                          className={`w-6 h-6 rounded-full flex items-center justify-center text-xs font-semibold shrink-0 ${
                            isCompleted
                              ? "bg-primary text-white"
                              : isCurrent
                              ? "bg-primary text-white"
                              : "bg-gray-lightest text-gray border border-gray-light"
                          }`}
                        >
                          {isCompleted ? (
                            <svg
                              className="w-4 h-4"
                              fill="currentColor"
                              viewBox="0 0 20 20"
                            >
                              <path
                                fillRule="evenodd"
                                d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z"
                                clipRule="evenodd"
                              />
                            </svg>
                          ) : (
                            step.number
                          )}
                        </div>
                        <span
                          className={`text-sm font-medium ${
                            isCurrent
                              ? "text-gray-dark"
                              : isCompleted
                              ? "text-gray"
                              : "text-gray"
                          }`}
                        >
                          {step.label}
                        </span>
                      </div>
                    );
                  })}
                </div>
              </div>

              {/* Help Section */}
              <div className="mt-6 pt-6 border-t border-gray-light">
                <div className="flex items-start gap-3 text-xs text-gray">
                  <svg
                    className="w-4 h-4 text-success shrink-0 mt-0.5"
                    fill="currentColor"
                    viewBox="0 0 20 20"
                  >
                    <path
                      fillRule="evenodd"
                      d="M5 9V7a5 5 0 0110 0v2a2 2 0 012 2v5a2 2 0 01-2 2H5a2 2 0 01-2-2v-5a2 2 0 012-2zm8-2v2H7V7a3 3 0 016 0z"
                      clipRule="evenodd"
                    />
                  </svg>
                  <span>We take strong measures to protect your information.</span>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
